  // Catalogue filters: customType, locales, statuses, releaseIds, tags, date bounds. A document matches tags when it carries any listed tag. Tags match exactly and are case sensitive. customType is required when where is set. Scope alone lists every document in that slice — set where too for a field-value filter.
  scope?: { customType?: string; firstPublishedAt?: { after?: string; before?: string; }; lastModifiedAt?: { after?: string; before?: string; }; locales?: Array<string>; releaseIds?: Array<string>; statuses?: Array<"draft" | "published" | "release">; tags?: Array<string>; };
